export class DERMUtils {
  static search(query: string): SpecialtyCodeEntry[] {
    const q = query.toLowerCase();
    return DERM_SPECIALTY_DATABASE.filter(item => item.code.toLowerCase().includes(q) || item.description.toLowerCase().includes(q));
  }
}
